CREATE TABLE agent_till (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  agent_outlet_id              uuid NOT NULL REFERENCES agent_outlet(id),
  till_number                  varchar(32) NOT NULL,
  operator_user_id             uuid,
  status                       varchar(40) NOT NULL DEFAULT 'CLOSED' CHECK (status IN ('OPEN', 'CLOSED', 'SUSPENDED')),
  currency                     char(3) NOT NULL,
  opened_at                    timestamptz,
  closed_at                    timestamptz,
  opening_cash                 numeric(28,8),
  cash_in_total                numeric(28,8),
  cash_out_total               numeric(28,8),
  expected_cash                numeric(28,8),
  declared_cash                numeric(28,8),
  variance                     numeric(28,8),
  variance_status              varchar(40) CHECK (variance_status IN ('BALANCED', 'OVER', 'SHORT')),
  denominations                jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_agent_till_till_number UNIQUE (tenant_id, till_number)
);
COMMENT ON TABLE agent_till IS 'A cash till at an outlet, opened and closed per shift with cash counts';
COMMENT ON COLUMN agent_till.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN agent_till.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN agent_till.created_at IS 'Creation time';
COMMENT ON COLUMN agent_till.created_by IS 'Principal that created the row';
COMMENT ON COLUMN agent_till.updated_at IS 'Last update time';
COMMENT ON COLUMN agent_till.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN agent_till.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN agent_till.agent_outlet_id IS 'Outlet';
COMMENT ON COLUMN agent_till.till_number IS 'Till number';
COMMENT ON COLUMN agent_till.operator_user_id IS 'Operator on shift';
COMMENT ON COLUMN agent_till.status IS 'Status';
COMMENT ON COLUMN agent_till.currency IS 'Currency';
COMMENT ON COLUMN agent_till.opened_at IS 'Shift start';
COMMENT ON COLUMN agent_till.closed_at IS 'Shift end';
COMMENT ON COLUMN agent_till.opening_cash IS 'Declared cash at opening';
COMMENT ON COLUMN agent_till.cash_in_total IS 'Cash received from customers during the shift (cash-in)';
COMMENT ON COLUMN agent_till.cash_out_total IS 'Cash paid to customers during the shift (cash-out)';
COMMENT ON COLUMN agent_till.expected_cash IS 'Opening cash + cash-in - cash-out';
COMMENT ON COLUMN agent_till.declared_cash IS 'Declared cash at closing';
COMMENT ON COLUMN agent_till.variance IS 'Declared minus expected';
COMMENT ON COLUMN agent_till.variance_status IS 'Balanced, over or short';
COMMENT ON COLUMN agent_till.denominations IS 'Cash count by denomination, e.g. {"1000": 12, "500": 3}';
COMMENT ON COLUMN agent_till.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN agent_till.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN agent_till.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN agent_till.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN agent_till.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_agent_till_tenant ON agent_till (tenant_id, created_at);
CREATE INDEX ix_agent_till_agent_outlet_id ON agent_till (agent_outlet_id);
CREATE INDEX ix_agent_till_operator_user_id ON agent_till (operator_user_id);
ALTER TABLE agent_till ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON agent_till USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_agent_till_touch BEFORE UPDATE ON agent_till FOR EACH ROW EXECUTE FUNCTION touch_row();

-- agent_device: A POS terminal or phone used by an agent
CREATE TABLE agent_device (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  agent_id                     uuid NOT NULL REFERENCES agent(id),
  agent_outlet_id              uuid REFERENCES agent_outlet(id),
  device_type                  varchar(40) NOT NULL CHECK (device_type IN ('POS', 'SMARTPHONE', 'TABLET', 'FEATURE_PHONE')),
  serial_number                varchar(64) NOT NULL,
  imei                         varchar(20),
  model                        varchar(64),
  os_version                   varchar(32),
  app_version                  varchar(32),
  sim_msisdn                   varchar(20),
  status                       varchar(40) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE', 'LOST', 'RETIRED')),
  status_reason                varchar(255),
  assigned_at                  timestamptz,
  last_seen_at                 timestamptz,
  last_latitude                numeric(18,10),
  last_longitude               numeric(18,10),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_agent_device_serial_number UNIQUE (tenant_id, serial_number)
);
COMMENT ON TABLE agent_device IS 'A POS terminal or phone used by an agent';
COMMENT ON COLUMN agent_device.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN agent_device.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN agent_device.created_at IS 'Creation time';
