COMMENT ON COLUMN agent_device.updated_at IS 'Last update time';
COMMENT ON COLUMN agent_device.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN agent_device.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN agent_device.agent_id IS 'Agent';
COMMENT ON COLUMN agent_device.agent_outlet_id IS 'Outlet';
COMMENT ON COLUMN agent_device.device_type IS 'Device type';
COMMENT ON COLUMN agent_device.serial_number IS 'Serial number';
COMMENT ON COLUMN agent_device.imei IS 'IMEI';
COMMENT ON COLUMN agent_device.model IS 'Model';
COMMENT ON COLUMN agent_device.os_version IS 'OS version';
COMMENT ON COLUMN agent_device.app_version IS 'Agent app version';
COMMENT ON COLUMN agent_device.sim_msisdn IS 'SIM number';
COMMENT ON COLUMN agent_device.status IS 'Status';
COMMENT ON COLUMN agent_device.status_reason IS 'Reason for the current status';
COMMENT ON COLUMN agent_device.assigned_at IS 'Assignment time';
COMMENT ON COLUMN agent_device.last_seen_at IS 'Last heartbeat';
COMMENT ON COLUMN agent_device.last_latitude IS 'Last known latitude';
COMMENT ON COLUMN agent_device.last_longitude IS 'Last known longitude';
COMMENT ON COLUMN agent_device.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN agent_device.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN agent_device.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN agent_device.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN agent_device.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_agent_device_tenant ON agent_device (tenant_id, created_at);
CREATE INDEX ix_agent_device_agent_id ON agent_device (agent_id);
CREATE INDEX ix_agent_device_agent_outlet_id ON agent_device (agent_outlet_id);
