-- cash_management_request: Cash-in-transit delivery or pickup request for an outlet
CREATE TABLE cash_management_request (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  agent_outlet_id              uuid NOT NULL REFERENCES agent_outlet(id),
  request_type                 varchar(40) NOT NULL CHECK (request_type IN ('CASH_DELIVERY', 'CASH_PICKUP')),
